import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";

/**
 * The bootstrap code, and proving you have it without sending it.
 *
 * The code is generated by the install script, printed in the operator's terminal, and written beside
 * the install with mode 600. It answers one question — is the person opening this UI the person who ran
 * the installer — and it stops being interesting the moment a real operator account exists.
 *
 * It is never transmitted. The browser proves knowledge of it: the server issues a nonce, the page
 * returns `HMAC(code, nonce)`, and a session is issued against that. So a channel that turns out not to
 * be encrypted, or a proxy logging request bodies, does not end up holding the credential to the machine.
 *
 * What that does not defend against is an active attacker who can rewrite the page doing the HMAC — which
 * is why the installer establishes TLS before this server starts, rather than the other way round. This
 * is the second lock, not the first.
 */

/** How long a challenge is good for. Long enough to type a code, short enough not to accumulate. */
const CHALLENGE_TTL_MS = 2 * 60 * 1000;

/** Failures before the code stops answering, and for how long. */
const MAX_FAILURES = 5;
const LOCKOUT_MS = 30 * 1000;

export interface Challenge {
    readonly id: string;
    readonly nonce: string;
    readonly expiresAt: number;
}

export interface Session {
    readonly token: string;
    readonly issuedAt: number;
}

export type VerifyResult =
    | { ok: true; session: Session }
    | { ok: false; reason: "unknown-challenge" | "expired" | "mismatch" | "locked" | "spent"; retryAfterMs?: number };

/**
 * Holds the code and the challenges outstanding against it.
 *
 * One instance per process. It is deliberately not durable: a restart invalidates every challenge and
 * every session, which is the correct behaviour for a thing that exists for the length of one setup.
 */
export class BootstrapAuth {
    readonly #code: Buffer;
    readonly #challenges = new Map<string, Challenge>();
    readonly #sessions = new Set<string>();

    #failures = 0;
    #lockedUntil = 0;
    #retired = false;

    /** Argon2id, as `Bun.password.hash` produced it. Absent until the operator sets one. */
    #passwordHash: string | undefined;

    constructor(code: string) {
        if (code.trim().length === 0)
            throw new Error("the bootstrap code is empty; the installer did not write one");

        this.#code = Buffer.from(code.trim(), "utf8");
    }

    /**
     * Issues a nonce to prove against.
     *
     * Handed out without any credential, on purpose: a challenge is worthless on its own, and refusing
     * to issue one before authentication would mean authenticating before authentication. What stops it
     * being a way to farm work is that each one is small, single-use and short-lived.
     */
    challenge(now = Date.now()): Challenge {
        this.#sweep(now);

        const challenge: Challenge = {
            id: randomBytes(16).toString("hex"),
            nonce: randomBytes(32).toString("hex"),
            expiresAt: now + CHALLENGE_TTL_MS,
        };

        this.#challenges.set(challenge.id, challenge);

        return challenge;
    }

    /**
     * Checks a proof and, if it holds, issues a session.
     *
     * The challenge is consumed whether or not the proof was right. A challenge that survives a failed
     * attempt is an oracle: it lets somebody try answers against one nonce until they find it, which is
     * the whole attack this is meant to make expensive.
     */
    verify(challengeId: string, proof: string, now = Date.now()): VerifyResult {
        if (this.#retired)
            return { ok: false, reason: "spent" };

        if (now < this.#lockedUntil)
            return { ok: false, reason: "locked", retryAfterMs: this.#lockedUntil - now };

        const challenge = this.#challenges.get(challengeId);

        if (challenge === undefined)
            return { ok: false, reason: "unknown-challenge" };

        this.#challenges.delete(challengeId);

        if (now >= challenge.expiresAt)
            return { ok: false, reason: "expired" };

        if (!this.#proofHolds(challenge.nonce, proof)) return this.#refuse(now);

        return this.#admit(now);
    }

    /**
     * The other door: the password the operator set during setup.
     *
     * It exists because the code has to stop working. The code is printed in a terminal, sits in a file
     * in the install root, and opens a panel that holds the docker socket — leaving it valid forever
     * would, as §4 puts it, replace one problem with a worse one. But retiring it with nothing to take
     * its place locks the operator out of their own machine, so the two are one change: a password is
     * required before the install runs, and the code is retired the moment the install succeeds.
     *
     * Shares the lockout with the code deliberately. There is one door's worth of patience here, not
     * two, and an attacker who could burn five attempts on each in turn would have twice the budget.
     */
    async verifyPassword(password: string, now = Date.now()): Promise<VerifyResult> {
        if (this.#passwordHash === undefined) return { ok: false, reason: "unknown-challenge" };

        if (now < this.#lockedUntil) return { ok: false, reason: "locked", retryAfterMs: this.#lockedUntil - now };

        // Argon2id, so a wrong answer costs real time and memory rather than a string comparison. That
        // is the point of it: this credential outlives setup, on a box facing the internet.
        const holds = await Bun.password.verify(password, this.#passwordHash).catch(() => false);

        return holds ? this.#admit(now) : this.#refuse(now);
    }

    /**
     * Takes the hash the panel should accept from now on.
     *
     * A hash, never a password: this class does not choose the cost parameters and does not read the
     * disk. Whoever stores it hashes it — see `panelCredential` in `config.ts`.
     */
    adoptPassword(hash: string | undefined): void {
        this.#passwordHash = hash;
    }

    /** Whether there is a second door yet. Nothing may retire the code before there is. */
    get hasPassword(): boolean {
        return this.#passwordHash !== undefined;
    }

    /** One wrong answer, at whichever door. */
    #refuse(now: number): VerifyResult {
        this.#failures += 1;

        if (this.#failures >= MAX_FAILURES) {
            // Locked globally rather than per address, because there is no identity here to lock and a
            // source address is whatever a proxy last wrote in a header. The cost is that somebody who
            // can reach the port can also lock the operator out for half a minute — a nuisance, and a
            // cheaper one than a credential that can be ground down at line rate.
            this.#lockedUntil = now + LOCKOUT_MS;
            this.#failures = 0;
        }

        return { ok: false, reason: "mismatch" };
    }

    #admit(now: number): VerifyResult {
        this.#failures = 0;

        const session: Session = { token: randomBytes(32).toString("hex"), issuedAt: now };

        this.#sessions.add(session.token);

        return { ok: true, session };
    }

    /** Whether a session token was issued by this process and has not been retired. */
    holds(token: string | undefined): boolean {
        return token !== undefined && this.#sessions.has(token);
    }

    /**
     * Ends the bootstrap credential's life, once setup has produced a real operator account.
     *
     * Existing sessions survive so the panel does not log the operator out at the moment it becomes the
     * panel. What ends is the ability to obtain a new one from the code, which is the thing that must not
     * outlive setup on a machine facing the internet.
     */
    retire(): void {
        // Refused rather than obeyed, because the caller cannot see what it would cost. Retiring with no
        // password set removes the only way into a panel that is now the machine's control surface, and
        // nothing short of editing files on the host would get it back.
        if (this.#passwordHash === undefined)
            throw new Error("the bootstrap code cannot be retired before a panel password exists: there would be no way in");

        this.#retired = true;
        this.#challenges.clear();
    }

    get retired(): boolean {
        return this.#retired;
    }

    #proofHolds(nonce: string, proof: string): boolean {
        const expected = createHmac("sha256", this.#code).update(nonce).digest();

        let given: Buffer;

        try {
            given = Buffer.from(proof, "hex");
        } catch {
            return false;
        }

        // Length is checked first because timingSafeEqual throws on a mismatch rather than returning
        // false, and a thrown exception is a timing signal of its own.
        return given.length === expected.length && timingSafeEqual(given, expected);
    }

    #sweep(now: number): void {
        for (const [id, challenge] of this.#challenges)
            if (now >= challenge.expiresAt) this.#challenges.delete(id);
    }
}

/** What the page computes. Exported so the test proves the two sides agree rather than assuming it. */
export function proofFor(code: string, nonce: string): string {
    return createHmac("sha256", code).update(nonce).digest("hex");
}
